/**
 * The flag usage groups of `szflags.json`: which flags apply to which engine methods.
 *
 * @property altName The group's `szflags.json` name (for example `SzEntityFlags`).
 * @property allFlags Every flag that applies to this group (empty when the group's methods
 *   take no flags).
 */
public enum class SzFlagUsageGroup(
    public val altName: String,
    public val allFlags: SzFlags,
) {
    /** `SzAddRecordFlags`. */
    ADD_RECORD("SzAddRecordFlags", SzFlags(0x4000_0000_0000_0000L)),

    /** `SzDeleteRecordFlags`. */
    DELETE_RECORD("SzDeleteRecordFlags", SzFlags(0x4000_0000_0000_0000L)),

    /** `SzEntityFlags`. */
    ENTITY("SzEntityFlags", SzFlags(0x0000_029C_B1FD_FFC0L)),

    /** `SzExportFlags`. */
    EXPORT("SzExportFlags", SzFlags(0x0000_029C_B1FD_FFFFL)),

    /** `SzFindInterestingEntitiesFlags`. */
    FIND_INTERESTING_ENTITIES("SzFindInterestingEntitiesFlags", SzFlags(0x0000_0000_0000_0000L)),

    /** `SzFindNetworkFlags`. */
    FIND_NETWORK("SzFindNetworkFlags", SzFlags(0x0000_029E_B1FD_FFC0L)),

    /** `SzFindPathFlags`. */
    FIND_PATH("SzFindPathFlags", SzFlags(0x0000_029C_F3FD_FFC0L)),

    /** `SzHowFlags`. */
    HOW("SzHowFlags", SzFlags(0x0000_0004_0400_0000L)),

    /** `SzRecordFlags`. */
    RECORD("SzRecordFlags", SzFlags(0x0000_0298_8085_0000L)),

    /** `SzRecordPreviewFlags`. */
    RECORD_PREVIEW("SzRecordPreviewFlags", SzFlags(0x0000_0218_8085_0000L)),

    /** `SzRedoFlags`. */
    REDO("SzRedoFlags", SzFlags(0x4000_0000_0000_0000L)),

    /** `SzReevaluateEntityFlags`. */
    REEVALUATE_ENTITY("SzReevaluateEntityFlags", SzFlags(0x4000_0000_0000_0000L)),

    /** `SzReevaluateRecordFlags`. */
    REEVALUATE_RECORD("SzReevaluateRecordFlags", SzFlags(0x4000_0000_0000_0000L)),

    /** `SzSearchFlags`. */
    SEARCH("SzSearchFlags", SzFlags(0x0000_02FD_BDFD_FFCFL)),

    /** `SzVirtualEntityFlags`. */
    VIRTUAL_ENTITY("SzVirtualEntityFlags", SzFlags(0x0000_0298_9185_FC00L)),

    /** `SzWhyEntitiesFlags`. */
    WHY_ENTITIES("SzWhyEntitiesFlags", SzFlags(0x0000_029C_B5FD_FFC0L)),

    /** `SzWhyRecordInEntityFlags`. */
    WHY_RECORD_IN_ENTITY("SzWhyRecordInEntityFlags", SzFlags(0x0000_029C_B5FD_FFC0L)),

    /** `SzWhyRecordsFlags`. */
    WHY_RECORDS("SzWhyRecordsFlags", SzFlags(0x0000_029C_B5FD_FFC0L)),

    /** `SzWhySearchFlags`. */
    WHY_SEARCH("SzWhySearchFlags", SzFlags(0x0000_02FC_BDFD_FFC0L)),
    ;

    public companion object {
        /** The group with a `szflags.json` name, or null. */
        public fun fromAltName(altName: String): SzFlagUsageGroup? = entries.firstOrNull { it.altName == altName }
    }
}
